      context, params, grad_in, argmax, grad_out, include_batch_in_index_);
}

static inline mp_ubyte safeRead(const mp_ubyte* buffer, mp_uint32& index, mp_uint32 size, mp_ubyte errorValue = 0)
{
	if (index < size)
	{
		return buffer[index++];
	}

	index++;
	return errorValue;
}

void Compute(OpKernelContext* context) override {
  const Tensor& x = context->input(0);
  const Tensor& y = context->input(1);
  const float min_x = context->input(2).flat<float>()(0);
  const float max_x = context->input(3).flat<float>()(0);
  const float min_y = context->input(4).flat<float>()(0);
  const float max_y = context->input(5).flat<float>()(0);

  BCast bcast(BCast::FromShape(x.shape()), BCast::FromShape(y.shape()));
  if (!bcast.IsValid()) {
    context->SetStatus(errors::InvalidArgument(
        "Incompatible shapes: ", x.shape().DebugString(), " vs. ",
        y.shape().DebugString()));
    return;
  }
  Tensor* z;
  OP_REQUIRES_OK(context, context->allocate_output(
                              0, BCast::ToShape(bcast.output_shape()), &z));

  // Make sure that we have valid quantization ranges for the input buffers.
  // If the difference between the min and max is negative or zero, it makes
  // it hard to do meaningful intermediate operations on the values.
  OP_REQUIRES(context, (max_x > min_x),
              errors::InvalidArgument("max_x must be larger than min_a."));
  OP_REQUIRES(context, (max_y > min_y),
              errors::InvalidArgument("max_x must be larger than min_b."));
  const int32 offset_x = FloatToQuantizedUnclamped<T>(0.0f, min_x, max_x);
  const int32 offset_y = FloatToQuantizedUnclamped<T>(0.0f, min_y, max_y);
  const T* x_data = x.flat<T>().data();
  const T* y_data = y.flat<T>().data();
  Toutput* z_data = z->flat<Toutput>().data();

  const int ndims = bcast.x_reshape().size();
  if (ndims <= 1) {
    if (x.NumElements() == 1) {
      ScalarMultiply<T, Toutput>(context, y_data, offset_y, y.NumElements(),
                                 x_data[0], offset_x, z_data);
    } else if (y.NumElements() == 1) {
      ScalarMultiply<T, Toutput>(context, x_data, offset_x, x.NumElements(),
                                 y_data[0], offset_y, z_data);
    } else {
      VectorMultiply<T, Toutput>(context, x_data, offset_x, y_data, offset_y,
                                 x.NumElements(), z_data);
    }
  } else if (ndims == 2) {
    const T* vector_data;
    int64 vector_num_elements;
    int32 vector_offset;
    const T* tensor_data;
    int64 tensor_num_elements;
    int32 tensor_offset;
    if (x.NumElements() < y.NumElements()) {
      vector_data = x_data;
      vector_num_elements = x.NumElements();
      vector_offset = offset_x;
      tensor_data = y_data;
      tensor_num_elements = y.NumElements();
      tensor_offset = offset_y;
    } else {
      vector_data = y_data;
      vector_num_elements = y.NumElements();
      vector_offset = offset_y;
      tensor_data = x_data;
      tensor_num_elements = x.NumElements();
      tensor_offset = offset_x;
    }
    VectorTensorMultiply<T, Toutput>(
        vector_data, vector_offset, vector_num_elements, tensor_data,
        tensor_offset, tensor_num_elements, z_data);
  } else {
    LOG(INFO) << "ndims=" << ndims;
    LOG(INFO) << "bcast.x_reshape()="
              << TensorShape(bcast.x_reshape()).DebugString();
    LOG(INFO) << "bcast.y_reshape()="
              << TensorShape(bcast.y_reshape()).DebugString();
    LOG(INFO) << "bcast.x_bcast()="
              << TensorShape(bcast.x_bcast()).DebugString();
    LOG(INFO) << "bcast.y_bcast()="
              << TensorShape(bcast.y_bcast()).DebugString();

    context->SetStatus(errors::Unimplemented(
        "Broadcast between ", context->input(0).shape().DebugString(),
        " and ", context->input(1).shape().DebugString(),
        " is not supported yet."));
    return;
  }

  float min_z_value;
  float max_z_value;
  QuantizationRangeForMultiplication<T, T, Toutput>(
      min_x, max_x, min_y, max_y, &min_z_value, &max_z_value);
  Tensor* z_min = nullptr;
  OP_REQUIRES_OK(context, context->allocate_output(1, {}, &z_min));
  z_min->flat<float>()(0) = min_z_value;

  Tensor* z_max = nullptr;
  OP_REQUIRES_OK(context, context->allocate_output(2, {}, &z_max));
  z_max->flat<float>()(0) = max_z_value;
}

bool SharedMemory::Create(const SharedMemoryCreateOptions& options) {
  DCHECK_EQ(-1, mapped_file_);
  if (options.size == 0) return false;

  if (options.size > static_cast<size_t>(std::numeric_limits<int>::max()))
    return false;

  base::ThreadRestrictions::ScopedAllowIO allow_io;

  FILE *fp;
  bool fix_size = true;

  FilePath path;
  if (options.name == NULL || options.name->empty()) {
    DCHECK(!options.open_existing);
    fp = file_util::CreateAndOpenTemporaryShmemFile(&path, options.executable);

    if (fp) {
      if (unlink(path.value().c_str()))
        PLOG(WARNING) << "unlink";
    }
  } else {
     if (!FilePathForMemoryName(*options.name, &path))
       return false;

    fp = file_util::OpenFile(path, "w+x");
    if (fp == NULL && options.open_existing) {
      fp = file_util::OpenFile(path, "a+");
       fix_size = false;
     }
   }
   if (fp && fix_size) {
    struct stat stat;
    if (fstat(fileno(fp), &stat) != 0) {
      file_util::CloseFile(fp);
      return false;
    }
    const size_t current_size = stat.st_size;
    if (current_size != options.size) {
      if (HANDLE_EINTR(ftruncate(fileno(fp), options.size)) != 0) {
        file_util::CloseFile(fp);
        return false;
      }
    }
    requested_size_ = options.size;
  }
  if (fp == NULL) {
#if !defined(OS_MACOSX)
    PLOG(ERROR) << "Creating shared memory in " << path.value() << " failed";
    FilePath dir = path.DirName();
    if (access(dir.value().c_str(), W_OK | X_OK) < 0) {
      PLOG(ERROR) << "Unable to access(W_OK|X_OK) " << dir.value();
      if (dir.value() == "/dev/shm") {
        LOG(FATAL) << "This is frequently caused by incorrect permissions on "
                   << "/dev/shm.  Try 'sudo chmod 1777 /dev/shm' to fix.";
      }
    }
#else
    PLOG(ERROR) << "Creating shared memory in " << path.value() << " failed";
#endif
    return false;
  }

  return PrepareMapFile(fp);
}

void Compute(OpKernelContext* ctx) override {
  const Tensor* inputs;
  const Tensor* labels_indices;
  const Tensor* labels_values;
  const Tensor* seq_len;
  OP_REQUIRES_OK(ctx, ctx->input("inputs", &inputs));
  OP_REQUIRES_OK(ctx, ctx->input("labels_indices", &labels_indices));
  OP_REQUIRES_OK(ctx, ctx->input("labels_values", &labels_values));
  OP_REQUIRES_OK(ctx, ctx->input("sequence_length", &seq_len));

  OP_REQUIRES(ctx, inputs->shape().dims() == 3,
              errors::InvalidArgument("inputs is not a 3-Tensor"));
  OP_REQUIRES(ctx, TensorShapeUtils::IsVector(seq_len->shape()),
              errors::InvalidArgument("sequence_length is not a vector"));
  OP_REQUIRES(ctx, TensorShapeUtils::IsMatrix(labels_indices->shape()),
              errors::InvalidArgument("labels_indices is not a matrix"));
  OP_REQUIRES(ctx, labels_indices->dim_size(1) > 1,
              errors::InvalidArgument(
                  "labels_indices second dimension must be >= 1. Received ",
                  labels_indices->dim_size(1)));
  OP_REQUIRES(ctx, TensorShapeUtils::IsVector(labels_values->shape()),
              errors::InvalidArgument("labels_values is not a vector"));

  const TensorShape& inputs_shape = inputs->shape();
  const int64 max_time = inputs_shape.dim_size(0);
  OP_REQUIRES(ctx, max_time != 0,
              errors::InvalidArgument(
                  "Max time or first dimension of input cannot be 0."));
  const int64 batch_size = inputs_shape.dim_size(1);
  const int64 num_classes_raw = inputs_shape.dim_size(2);
  OP_REQUIRES(
      ctx, FastBoundsCheck(num_classes_raw, std::numeric_limits<int>::max()),
      errors::InvalidArgument("num_classes cannot exceed max int"));
  const int num_classes = static_cast<const int>(num_classes_raw);

  OP_REQUIRES(
      ctx, batch_size == seq_len->dim_size(0),
      errors::InvalidArgument("len(sequence_length) != batch_size.  ",
                              "len(sequence_length):  ", seq_len->dim_size(0),
                              " batch_size: ", batch_size));
  auto seq_len_t = seq_len->vec<int32>();

  OP_REQUIRES(ctx, labels_indices->dim_size(0) == labels_values->dim_size(0),
              errors::InvalidArgument(
                  "labels_indices and labels_values must contain the "
                  "same number of rows, but saw shapes: ",
                  labels_indices->shape().DebugString(), " vs. ",
                  labels_values->shape().DebugString()));

  OP_REQUIRES(ctx, batch_size != 0,
              errors::InvalidArgument("batch_size must not be 0"));

  // Figure out the maximum label length to use as sparse tensor dimension.
  auto labels_indices_t = labels_indices->matrix<int64>();
  int64 max_label_len = 0;
  for (int i = 0; i < labels_indices->dim_size(0); i++) {
    max_label_len = std::max(max_label_len, labels_indices_t(i, 1) + 1);
  }

  TensorShape labels_shape({batch_size, max_label_len});
  std::vector<int64> order{0, 1};
  sparse::SparseTensor labels_sp;
  OP_REQUIRES_OK(
      ctx, sparse::SparseTensor::Create(*labels_indices, *labels_values,
                                        labels_shape, order, &labels_sp));

  Status labels_sp_valid = labels_sp.IndicesValid();
  OP_REQUIRES(ctx, labels_sp_valid.ok(),
              errors::InvalidArgument("label SparseTensor is not valid: ",
                                      labels_sp_valid.error_message()));

  typename ctc::CTCLossCalculator<T>::LabelSequences labels_t(batch_size);
  for (const auto& g : labels_sp.group({0})) {  // iterate by batch
    const int64 batch_indices = g.group()[0];
    OP_REQUIRES(ctx, FastBoundsCheck(batch_indices, batch_size),
                errors::InvalidArgument("labels batch index must be between ",
                                        0, " and ", batch_size,
                                        " but saw: ", batch_indices));

    auto values = g.values<int32>();
    std::vector<int>* b_values = &labels_t[batch_indices];
    b_values->resize(values.size());
    for (int i = 0; i < values.size(); ++i) (*b_values)[i] = values(i);
  }

  OP_REQUIRES(ctx, static_cast<size_t>(batch_size) == labels_t.size(),
              errors::InvalidArgument("len(labels) != batch_size.  ",
                                      "len(labels):  ", labels_t.size(),
                                      " batch_size: ", batch_size));

  for (int64 b = 0; b < batch_size; ++b) {
    OP_REQUIRES(
        ctx, seq_len_t(b) <= max_time,
        errors::InvalidArgument("sequence_length(", b, ") <= ", max_time));
  }

  Tensor* loss = nullptr;
  OP_REQUIRES_OK(ctx, ctx->allocate_output("loss", seq_len->shape(), &loss));
  auto loss_t = loss->vec<T>();

  Tensor* gradient;
  OP_REQUIRES_OK(ctx,
                 ctx->allocate_output("gradient", inputs_shape, &gradient));
  auto gradient_t = gradient->tensor<T, 3>();
  auto inputs_t = inputs->tensor<T, 3>();
  std::vector<OutputMap> gradient_list_t;
  std::vector<InputMap> input_list_t;

  for (std::size_t t = 0; t < max_time; ++t) {
    input_list_t.emplace_back(inputs_t.data() + t * batch_size * num_classes,
                              batch_size, num_classes);
    gradient_list_t.emplace_back(
        gradient_t.data() + t * batch_size * num_classes, batch_size,
        num_classes);
  }

  gradient_t.setZero();

  // Assumption: the blank index is num_classes - 1
  ctc::CTCLossCalculator<T> ctc_loss_calculator(num_classes - 1, 0);
  DeviceBase::CpuWorkerThreads workers =
      *ctx->device()->tensorflow_cpu_worker_threads();
  OP_REQUIRES_OK(ctx, ctc_loss_calculator.CalculateLoss(
                          seq_len_t, labels_t, input_list_t,
                          preprocess_collapse_repeated_, ctc_merge_repeated_,
                          ignore_longer_outputs_than_inputs_, &loss_t,
                          &gradient_list_t, &workers));
}

